import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { MapContainer, TileLayer, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import './Simulador.css';

// Fix for default markers
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// Custom airplane icon based on saturation
// Crear diferentes tipos de iconos de aviones más realistas similar a la imagen
const createAirplaneIcon = (type, color, rotation = 0) => {
  const iconSvg = {
    'boeing737': `
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
        <!-- Fuselaje -->
        <ellipse cx="10" cy="10" rx="1.5" ry="8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas principales -->
        <ellipse cx="10" cy="8" rx="7" ry="1.2" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas traseras -->
        <ellipse cx="10" cy="14" rx="3" ry="0.8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Cola vertical -->
        <path d="M10 16 L10 18 L9.5 18 L9.5 16 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/>
      </svg>
    `,
    'airbus320': `
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
        <!-- Fuselaje -->
        <ellipse cx="10" cy="10" rx="1.8" ry="9" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas principales -->
        <ellipse cx="10" cy="7.5" rx="8" ry="1.5" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas traseras -->
        <ellipse cx="10" cy="14.5" rx="3.5" ry="1" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Cola vertical -->
        <path d="M10 16.5 L10 18.5 L9.2 18.5 L9.2 16.5 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/>
      </svg>
    `,
    'boeing777': `
      <svg width="22" height="22" viewBox="0 0 22 22" fill="none" xmlns="http://www.w3.org/2000/svg">
        <!-- Fuselaje -->
        <ellipse cx="11" cy="11" rx="2" ry="10" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas principales -->
        <ellipse cx="11" cy="8" rx="9" ry="1.8" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Alas traseras -->
        <ellipse cx="11" cy="15" rx="4" ry="1.2" fill="${color}" stroke="#ffffff" stroke-width="0.5"/>
        <!-- Cola vertical -->
        <path d="M11 17 L11 19.5 L10 19.5 L10 17 Z" fill="${color}" stroke="#ffffff" stroke-width="0.3"/>
      </svg>
    `,
    'cargo': `
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <!-- Fuselaje más ancho -->
        <ellipse cx="12" cy="12" rx="2.5" ry="10" fill="${color}" stroke="#ffffff" stroke-width="0.6"/>
        <!-- Alas principales -->
        <ellipse cx="12" cy="9" rx="10" ry="2" fill="${color}" stroke="#ffffff" stroke-width="0.6"/>
        <!-- Alas traseras -->
        <ellipse cx="12" cy="16" rx="4.5" ry="1.3" fill="${color}" stroke="#ffffff" stroke-width="0.6"/>
        <!-- Cola vertical -->
        <path d="M12 18 L12 21 L11 21 L11 18 Z" fill="${color}" stroke="#ffffff" stroke-width="0.4"/>
      </svg>
    `
  };

  return L.divIcon({
    html: `<div style="transform: rotate(${rotation}deg); display: flex; align-items: center; justify-content: center; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.2));">
             ${iconSvg[type]}
           </div>`,
    className: 'airplane-icon',
    iconSize: type === 'cargo' ? [24, 24] : type === 'boeing777' ? [22, 22] : [20, 20],
    iconAnchor: type === 'cargo' ? [12, 12] : type === 'boeing777' ? [11, 11] : [10, 10],
    popupAnchor: [0, -12]
  });
};

// Custom airport icon - Improved to match reference image
const createAirportIcon = (isSede = false, saturation = 0) => {
  const size = isSede ? 28 : 20;
  const color = isSede ? '#dc3545' : saturation > 80 ? '#ff6b6b' : saturation > 60 ? '#ffa726' : '#4fc3f7';

  return new L.DivIcon({
    className: 'airport-marker',
    html: `
      <div style="
        background: ${color};
        border: 3px solid white;
        border-radius: 50%;
        width: ${size}px;
        height: ${size}px;
        display: flex;
        align-items: center;
        justify-content: center;
        box-shadow: 0 2px 8px rgba(0,0,0,0.3);
        position: relative;
      ">
        <i class="fas fa-plane" style="
          color: white;
          font-size: ${size * 0.5}px;
          transform: rotate(45deg);
        "></i>
        ${isSede ? '<div style="position: absolute; top: -3px; right: -3px; background: #ffd700; border: 1px solid white; border-radius: 50%; width: 8px; height: 8px;"></div>' : ''}
      </div>
    `,
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
};

// Component to update markers dynamically
function DynamicMarkers({ flights, airports, activeView }) {
  const map = useMap();
  const markersRef = useRef([]);

  useEffect(() => {
    // Clear existing markers
    markersRef.current.forEach(marker => map.removeLayer(marker));
    markersRef.current = [];

    // Add airport markers
    if (activeView === 'airports' || activeView === 'flights') {
      airports.forEach(airport => {
        const saturation = (airport.packages / airport.capacity) * 100;
        const icon = createAirportIcon(airport.isSede, saturation);

        const marker = L.marker([airport.lat, airport.lng], { icon })
          .bindPopup(`
            <div style="font-family: 'Segoe UI', sans-serif; min-width: 220px; background: white; color: #333; border-radius: 8px; padding: 15px;">
              <strong style="color: #007bff; font-size: 16px;">${airport.name}</strong>
              ${airport.isSede ? '<span style="background: #007bff; color: white; padding: 2px 8px; border-radius: 12px; font-size: 11px; margin-left: 8px; font-weight: bold;">SEDE</span>' : ''}
              <br/>
              <div style="margin-top: 12px; font-size: 13px; line-height: 1.4;">
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">País:</strong> <span style="color: #333;">${airport.country}</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Capacidad:</strong> <span style="color: #333;">${airport.capacity}</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Paquetes:</strong> <span style="color: #333;">${airport.packages}</span></div>
                <div style="margin: 6px 0; padding: 4px 0;"><strong style="color: #007bff;">Saturación:</strong> 
                  <span style="color: ${saturation > 80 ? '#dc3545' : saturation > 60 ? '#ffc107' : '#28a745'}; font-weight: bold;">
                    ${saturation.toFixed(1)}%
                  </span>
                </div>
              </div>
            </div>
          `);
        marker.addTo(map);
        markersRef.current.push(marker);
      });
    }

    // Add flight markers
    if (activeView === 'flights') {
      flights.forEach(flight => {
        const icon = createAirplaneIcon(flight.aircraftType, flight.aircraftColor, flight.rotation);
        const marker = L.marker([flight.currentLat, flight.currentLng], { icon })
          .bindPopup(`
            <div style="font-family: 'Segoe UI', sans-serif; min-width: 240px; background: white; color: #333; border-radius: 8px; padding: 15px;">
              <strong style="color: #007bff; font-size: 16px; display: flex; align-items: center; gap: 8px;">
                ✈️ Vuelo ${flight.id}
              </strong>
              <div style="margin-top: 12px; font-size: 13px; line-height: 1.4;">
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Aeronave:</strong> <span style="color: #333;">${flight.aircraftName}</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Origen:</strong> <span style="color: #333;">${flight.origin.name} (${flight.origin.code})</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Destino:</strong> <span style="color: #333;">${flight.destination.name} (${flight.destination.code})</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Progreso:</strong> 
                  <span style="color: #28a745; font-weight: bold;">${(flight.progress * 100).toFixed(1)}%</span>
                </div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Altitud:</strong> <span style="color: #333;">${Math.round(flight.altitude).toLocaleString()} ft</span></div>
                <div style="margin: 6px 0; padding: 4px 0; border-bottom: 1px solid #e0e0e0;"><strong style="color: #007bff;">Velocidad:</strong> <span style="color: #333;">${Math.round(flight.speed)} kts</span></div>
                <div style="margin: 6px 0; padding: 4px 0;"><strong style="color: #007bff;">Carga:</strong> <span style="color: #333;">${flight.currentPackages}/${flight.packageCapacity} paquetes</span></div>
                <div style="margin: 4px 0;"><strong>Estado:</strong> 
                  <span style="color: #17a2b8; font-weight: bold;">${flight.status}</span>
                </div>
              </div>
            </div>
          `);
        marker.addTo(map);
        markersRef.current.push(marker);
      });
    }

    return () => {
      markersRef.current.forEach(marker => map.removeLayer(marker));
      markersRef.current = [];
    };
  }, [flights, airports, activeView, map]);

  return null;
}

const Simulador = () => {
  const [flights, setFlights] = useState([]);
  const [currentTime, setCurrentTime] = useState(new Date(2024, 7, 27, 8, 0, 0));
  const [elapsedTime, setElapsedTime] = useState({ days: 0, hours: 0, minutes: 0 });
  const [isRunning, setIsRunning] = useState(true);
  const [speed, setSpeed] = useState(1);
  const [simulationStatus, setSimulationStatus] = useState('Monitoreo en tiempo real activo');
  const [activeView, setActiveView] = useState('flights');
  const intervalRef = useRef();

  const airports = useMemo(() => [
    // SEDE PRINCIPAL: LIMA, PERÚ
    { name: 'Lima-Jorge Chávez', code: 'LIM', lat: -12.0219, lng: -77.1143, capacity: 1200, packages: 980, isSede: true, region: 'América del Sur', country: 'Perú' },
    { name: 'Bogotá-El Dorado', code: 'BOG', lat: 4.7016, lng: -74.1469, capacity: 900, packages: 720, region: 'América del Sur', country: 'Colombia' },
    // SEDE PRINCIPAL: BRUSELAS, BÉLGICA
    { name: 'Bruselas', code: 'BRU', lat: 50.9010, lng: 4.4844, capacity: 1100, packages: 850, isSede: true, region: 'Europa', country: 'Bélgica' },
    { name: 'Amsterdam-Schiphol', code: 'AMS', lat: 52.3105, lng: 4.7683, capacity: 1200, packages: 960, region: 'Europa', country: 'Países Bajos' },
    { name: 'París-Charles de Gaulle', code: 'CDG', lat: 49.0097, lng: 2.5479, capacity: 1300, packages: 1040, region: 'Europa', country: 'Francia' },
    // SEDE PRINCIPAL: BAKU, AZERBAIYÁN
    { name: 'Baku-Heydar Aliyev', code: 'GYD', lat: 40.4675, lng: 50.0467, capacity: 1000, packages: 800, isSede: true, region: 'Asia Central', country: 'Azerbaiyán' },
    { name: 'Estambul', code: 'IST', lat: 41.2619, lng: 28.7419, capacity: 1100, packages: 880, region: 'Asia Central', country: 'Turquía' },
    { name: 'Dubai', code: 'DXB', lat: 25.2532, lng: 55.3657, capacity: 1200, packages: 960, region: 'Asia Central', country: 'EAU' },
    { name: 'Madrid-Barajas', code: 'MAD', lat: 40.4983, lng: -3.5676, capacity: 900, packages: 720, region: 'Europa', country: 'España' },
    { name: 'México City', code: 'MEX', lat: 19.4363, lng: -99.0721, capacity: 800, packages: 640, region: 'América del Norte', country: 'México' },
    { name: 'Londres-Heathrow', code: 'LHR', lat: 51.4700, lng: -0.4543, capacity: 1400, packages: 1120, region: 'Europa', country: 'Reino Unido' },
    { name: 'Frankfurt', code: 'FRA', lat: 50.0379, lng: 8.5622, capacity: 1250, packages: 1000, region: 'Europa', country: 'Alemania' }
  ], []);

  // Initialize flights
  const generateInitialFlights = useCallback(() => {
    const flightCount = 402;
    const newFlights = [];
    const sedes = airports.filter(a => a.isSede);

    // Tipos de aviones con colores normales y variados
    const flightTypes = [
      { type: 'boeing737', color: '#007bff', name: 'Boeing 737', capacity: [150, 250] },
      { type: 'boeing737', color: '#28a745', name: 'Boeing 737', capacity: [150, 250] },
      { type: 'boeing737', color: '#17a2b8', name: 'Boeing 737', capacity: [150, 250] },
      { type: 'airbus320', color: '#dc3545', name: 'Airbus A320', capacity: [180, 280] },
      { type: 'airbus320', color: '#ffc107', name: 'Airbus A320', capacity: [180, 280] },
      { type: 'airbus320', color: '#6f42c1', name: 'Airbus A320', capacity: [180, 280] },
      { type: 'boeing777', color: '#fd7e14', name: 'Boeing 777', capacity: [300, 400] },
      { type: 'boeing777', color: '#20c997', name: 'Boeing 777', capacity: [300, 400] },
      { type: 'cargo', color: '#6c757d', name: 'Cargo', capacity: [50, 150] },
      { type: 'cargo', color: '#495057', name: 'Cargo', capacity: [50, 150] }
    ];

    for (let i = 0; i < flightCount; i++) {
      let origin, destination;

      // 60% de los vuelos desde/hacia sedes principales
      if (Math.random() < 0.6) {
        const sede = sedes[Math.floor(Math.random() * sedes.length)];
        const otherAirports = airports.filter(a => a.region === sede.region && a !== sede);

        if (Math.random() < 0.5) {
          origin = sede;
          destination = otherAirports[Math.floor(Math.random() * otherAirports.length)] || 
                      airports[Math.floor(Math.random() * airports.length)];
        } else {
          destination = sede;
          origin = otherAirports[Math.floor(Math.random() * otherAirports.length)] || 
                 airports[Math.floor(Math.random() * airports.length)];
        }
      } else {
        origin = airports[Math.floor(Math.random() * airports.length)];
        destination = airports[Math.floor(Math.random() * airports.length)];
      }

      while (destination === origin) {
        destination = airports[Math.floor(Math.random() * airports.length)];
      }

      // Seleccionar tipo de avión
      const selectedType = flightTypes[Math.floor(Math.random() * flightTypes.length)];

      // Determinar saturación
      let saturation = 'low';
      const airportLoad = Math.random();
      if (airportLoad > 0.7) saturation = 'high';
      else if (airportLoad > 0.4) saturation = 'medium';

      // Calcular capacidad de paquetes basada en el tipo de avión
      const [minCap, maxCap] = selectedType.capacity;
      const packageCapacity = Math.floor(Math.random() * (maxCap - minCap + 1)) + minCap;

      const loadFactor = 0.7 + Math.random() * 0.3;
      const currentPackages = Math.floor(packageCapacity * loadFactor);

      // Calcular rotación basada en la dirección del vuelo
      const deltaLat = destination.lat - origin.lat;
      const deltaLng = destination.lng - origin.lng;
      const rotation = Math.atan2(deltaLng, deltaLat) * (180 / Math.PI);

      const flight = {
        id: `MP${String(i + 1).padStart(4, '0')}`,
        origin,
        destination,
        progress: Math.random() * 0.1, // Start near origin
        altitude: 0,
        speed: 0,
        status: 'active',
        saturation,
        packageCapacity,
        currentPackages,
        packageType: 'MPE',
        isSameContinentFlight: origin.region === destination.region,
        currentLat: origin.lat,
        currentLng: origin.lng,
        // Nuevos campos para tipo de avión
        aircraftType: selectedType.type,
        aircraftName: selectedType.name,
        aircraftColor: selectedType.color,
        rotation: rotation
      };

      newFlights.push(flight);
    }

    setFlights(newFlights);
  }, [airports]);

  useEffect(() => {
    generateInitialFlights();
  }, [generateInitialFlights]);

  // Simulation loop
  useEffect(() => {
    if (isRunning) {
      intervalRef.current = setInterval(() => {
        // Update time
        setCurrentTime(prev => {
          const newTime = new Date(prev);
          newTime.setMinutes(newTime.getMinutes() + speed);
          return newTime;
        });

        // Update elapsed time
        setElapsedTime(prev => {
          const totalMinutes = prev.days * 24 * 60 + prev.hours * 60 + prev.minutes + speed;
          return {
            days: Math.floor(totalMinutes / (24 * 60)),
            hours: Math.floor((totalMinutes % (24 * 60)) / 60),
            minutes: totalMinutes % 60
          };
        });

        // Update flights
        setFlights(prevFlights => {
          return prevFlights.map(flight => {
            let newProgress = flight.progress + (0.002 * speed);

            // Calculate new position
            const latDiff = flight.destination.lat - flight.origin.lat;
            const lngDiff = flight.destination.lng - flight.origin.lng;

            let newLat = flight.origin.lat + (latDiff * newProgress);
            let newLng = flight.origin.lng + (lngDiff * newProgress);

            // Update altitude and speed based on progress
            let newAltitude, newSpeed;
            if (newProgress < 0.1) {
              // Takeoff
              newAltitude = newProgress * 100000;
              newSpeed = newProgress * 2500;
            } else if (newProgress < 0.9) {
              // Cruise
              newAltitude = 30000 + Math.random() * 10000;
              newSpeed = 450 + Math.random() * 200;
            } else {
              // Landing
              const landingProgress = (newProgress - 0.9) / 0.1;
              newAltitude = 30000 * (1 - landingProgress);
              newSpeed = 450 * (1 - landingProgress * 0.6);
            }

            // Reset flight if completed
            if (newProgress >= 1) {
              // Generate new flight
              const newOrigin = airports[Math.floor(Math.random() * airports.length)];
              let newDestination = airports[Math.floor(Math.random() * airports.length)];
              while (newDestination === newOrigin) {
                newDestination = airports[Math.floor(Math.random() * airports.length)];
              }

              return {
                ...flight,
                origin: newOrigin,
                destination: newDestination,
                progress: 0,
                altitude: 0,
                speed: 0,
                currentLat: newOrigin.lat,
                currentLng: newOrigin.lng
              };
            }

            return {
              ...flight,
              progress: newProgress,
              altitude: newAltitude,
              speed: newSpeed,
              currentLat: newLat,
              currentLng: newLng
            };
          });
        });
      }, 1000);

      return () => clearInterval(intervalRef.current);
    } else {
      clearInterval(intervalRef.current);
    }
  }, [isRunning, speed, airports]);

  const handlePlay = () => {
    setIsRunning(true);
    setSimulationStatus('Simulación en ejecución');
  };

  const handlePause = () => {
    setIsRunning(false);
    setSimulationStatus('Simulación pausada');
  };

  const handleStop = () => {
    setIsRunning(false);
    setSimulationStatus('Simulación detenida');
  };

  const handleSpeedChange = () => {
    const speeds = [1, 2, 5, 10];
    const currentIndex = speeds.indexOf(speed);
    const nextSpeed = speeds[(currentIndex + 1) % speeds.length];
    setSpeed(nextSpeed);
  };

  const handleRestart = () => {
    setIsRunning(false);
    setElapsedTime({ days: 0, hours: 0, minutes: 0 });
    setCurrentTime(new Date(2024, 7, 27, 8, 0, 0));
    generateInitialFlights();
    setSimulationStatus('Sistema reiniciado');
    setTimeout(() => {
      setSimulationStatus('Monitoreo en tiempo real activo');
    }, 2000);
  };

  const formatTime = (timeObj) => {
    return `${timeObj.days.toString().padStart(2, '0')} : ${timeObj.hours.toString().padStart(2, '0')} : ${timeObj.minutes.toString().padStart(2, '0')}`;
  };

  const getSaturation = () => {
    const totalCapacity = airports.reduce((sum, airport) => sum + airport.capacity, 0);
    const totalPackages = airports.reduce((sum, airport) => sum + airport.packages, 0);
    return ((totalPackages / totalCapacity) * 100).toFixed(2);
  };

  const getMostSaturatedAirport = () => {
    return airports.reduce((max, airport) => {
      const saturation = (airport.packages / airport.capacity) * 100;
      const maxSaturation = (max.packages / max.capacity) * 100;
      return saturation > maxSaturation ? airport : max;
    });
  };

  const getFlightsByAltitude = () => {
    return flights.filter(f => f.altitude > 1000).length;
  };

  return (
    <div className="section-content active" id="simulationSection">
      {/* Sidebar Navigation for Simulation */}
      <div className="simulation-sidebar">
        <div className="sidebar-header">
          <h3><i className="fas fa-cogs"></i> Modos de Operación</h3>
        </div>
        <div className="sidebar-menu">
          <button className="sidebar-item active" data-mode="realtime">
            <i className="fas fa-broadcast-tower"></i>
            <span>Monitoreo en Tiempo Real</span>
          </button>
          <button className="sidebar-item disabled" data-mode="weekly" disabled>
            <i className="fas fa-calendar-week"></i>
            <span>Simulación Semanal</span>
            <small>Próximamente</small>
          </button>
          <button className="sidebar-item disabled" data-mode="collapse" disabled>
            <i className="fas fa-exclamation-triangle"></i>
            <span>Simulación de Colapso</span>
            <small>Próximamente</small>
          </button>
        </div>
      </div>

      {/* Main Simulation Content */}
      <div className="simulation-main-content">
        <div className="content-wrapper">
          <div className="control-panel">
            <h2>Monitoreo en Tiempo Real</h2>
          <div className="status-section">
            <span className="status-label">Estado de la Simulación:</span>
            <span className="status-text">{simulationStatus}</span>
          </div>

          <div className="simulation-controls">
            <h3><i className="fas fa-cogs"></i> Simulación</h3>
            <div className="control-buttons">
              <button className="sim-control-btn play-btn" onClick={handlePlay}>
                <i className="fas fa-play"></i> Iniciar
              </button>
              <button className="sim-control-btn pause-btn" onClick={handlePause}>
                <i className="fas fa-pause"></i> Pausar
              </button>
              <button className="sim-control-btn stop-btn" onClick={handleStop}>
                <i className="fas fa-stop"></i> Detener
              </button>
              <button className="sim-control-btn speed-btn" onClick={handleSpeedChange}>
                <i className="fas fa-tachometer-alt"></i> {speed}x
              </button>
              <button className="sim-control-btn restart-btn" onClick={handleRestart}>
                <i className="fas fa-redo-alt"></i> Reiniciar Todo
              </button>
            </div>
          </div>
        </div>

        {/* Controles del mapa */}
        <div className="map-controls-panel">
          <button 
            className={`map-btn vuelos-btn ${activeView === 'flights' ? 'active' : ''}`}
            onClick={() => setActiveView('flights')}
          >
            <i className="fas fa-plane"></i>
            Vuelos
          </button>
          <button 
            className={`map-btn rutas-btn ${activeView === 'routes' ? 'active' : ''}`}
            onClick={() => setActiveView('routes')}
          >
            <i className="fas fa-route"></i>
            Rutas
          </button>
          <button 
            className={`map-btn aeropuertos-btn ${activeView === 'airports' ? 'active' : ''}`}
            onClick={() => setActiveView('airports')}
          >
            <i className="fas fa-map-marker-alt"></i>
            Aeropuertos
          </button>
          <button className="map-btn mostrar-linea-btn">
            Mostrar Línea
          </button>
        </div>

        {/* Map Container */}
        <div className="map-container">
          <div className="map-area">
            <MapContainer
              center={[20.0, 10.0]}
              zoom={3}
              className="flight-map"
              scrollWheelZoom={true}
              dragging={true}
              minZoom={2}
              maxZoom={10}
              zoomControl={true}
              doubleClickZoom={true}
              boxZoom={true}
              keyboard={true}
              touchZoom={true}
              style={{ background: '#f8f9fa' }}
            >
              <TileLayer
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                attribution='© OpenStreetMap contributors'
                noWrap={true}
              />

              <DynamicMarkers 
                flights={flights} 
                airports={airports} 
                activeView={activeView} 
              />
            </MapContainer>
          </div>

          {/* Info Panel */}
          <div className="info-panel">
            <div className="info-header">
              <h3>Más información</h3>
              <button className="close-btn">
                <i className="fas fa-times"></i>
              </button>
            </div>

            <div className="time-section">
              <div className="current-time">
                <label>Hora actual:</label>
                <div className="time-display">
                  {currentTime.toLocaleDateString('es-ES')}, {currentTime.toLocaleTimeString('es-ES')}
                </div>
              </div>

              <div className="elapsed-time">
                <label>Tiempo transcurrido:</label>
                <div className="time-counter">{formatTime(elapsedTime)}</div>
              </div>
            </div>

            <div className="stats-section">
              <div className="stat-row">
                <span className="stat-label">Vuelos en el aire:</span>
                <span className="stat-value">{getFlightsByAltitude()}</span>
              </div>

              <div className="stat-row">
                <span className="stat-label">Saturación de aviones:</span>
                <span className="stat-value">{((getFlightsByAltitude() / 500) * 100).toFixed(2)}%</span>
              </div>

              <div className="stat-row">
                <span className="stat-label">Saturación de aeropuertos:</span>
                <span className="stat-value">{getSaturation()}%</span>
              </div>
            </div>

            <div className="airport-section">
              <h4>Aeropuertos más saturados</h4>
              <div className="airport-info">
                {(() => {
                  const mostSaturated = getMostSaturatedAirport();
                  const saturation = ((mostSaturated.packages / mostSaturated.capacity) * 100).toFixed(2);
                  return (
                    <>
                      <div className="airport-name">{mostSaturated.name}</div>
                      <div className="airport-details">
                        <div>Capacidad: {mostSaturated.capacity}</div>
                        <div>Paquetes: {mostSaturated.packages}</div>
                        <div className="saturation-highlight">Saturación: {saturation}%</div>
                      </div>
                    </>
                  );
                })()}
              </div>
            </div>
          </div>
        </div>
        </div>
      </div>
    </div>
  );
};

export default Simulador;
